(function(){
  'use strict';
  const units=window.HEAR_UNITS;
  let storage;try{storage=localStorage;}catch{storage=null;}
  const store=new HearStore.JournalStore(storage),reader=new HearAudio.Reader(),clips=new HearAudio.LocalRecordings(),recorder=new HearAudio.Recorder(clips);
  const pages=['home','practice','library','history','settings'];
  const modules={listen:'反复听',role:'角色扮演',retell:'故事复述',patterns:'主题句型',record:'录音练习',library:'表达收藏'};
  const ui={page:pages.includes(location.hash.slice(1))?location.hash.slice(1):'home',unit:store.state.last.unit,module:store.state.last.module,material:store.state.last.material,role:'',round:0,step:'listen',library:'patterns',shadow:-1,index:0,loop:false,hints:true,recConsent:false,pendingImport:null,epoch:0,speechPhase:'idle'};
  let recognition=null,recognizing=false,noticeTimer,notesTimer,clipUrls=new Map(),playback=null;
  const $=selector=>document.querySelector(selector);
  const h=text=>String(text??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${{play:'<path d="m9 5 10 7-10 7V5Z"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M6 4h12v17l-6-4-6 4V4Z"/>',mic:'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 10v2a6 6 0 0 0 12 0v-2M12 18v3M9 21h6"/>'}[name]||''}</svg>`;
  const button=(action,label,attrs='',type='')=>`<button type="button" data-action="${action}" ${attrs} class="${type}">${label}</button>`;
  const unit=()=>units.find(u=>u.id===ui.unit)||units[0];
  const allMaterials=u=>[...u.dialogues.map(m=>({...m,kind:'dialogue'})),...u.stories.map(m=>({...m,kind:'story'}))];
  function material(){const u=unit(),list=ui.module==='role'?u.dialogues:ui.module==='retell'?u.stories:allMaterials(u);return list.find(m=>m.id===ui.material)||list[0];}
  const key=()=>`${unit().id}/${material().id}`;
  const wordCount=m=>m.lines.map(l=>l.en).join(' ').match(/[A-Za-z]+(?:'[A-Za-z]+)?/g)?.length||0;
  const time=seconds=>`${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
  const dateText=iso=>new Date(iso).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
  function tell(message){$('#notice').textContent=message;$('#notice').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('visible'),5000);}
  store.onWarning=()=>{$('#storage-warning').hidden=false;};if(!store.persistent)store.onWarning();
  function remember(){store.state.last={unit:unit().id,module:ui.module,material:material().id};store.save();}
  function stopRecognition(){recognizing=false;try{recognition?.abort();}catch{}recognition=null;}
  function leave(){clearTimeout(notesTimer);recorder.cancelPending();if(recorder.active)recorder.stop();reader.stop();stopRecognition();document.querySelectorAll('audio').forEach(a=>a.pause());for(const url of clipUrls.values())URL.revokeObjectURL(url);clipUrls.clear();}
  function go(page){leave();ui.page=pages.includes(page)?page:'home';try{history.replaceState(null,'','#'+ui.page);}catch{}render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'});}
  function chooseMaterial(id){leave();ui.material=id;ui.round=0;ui.shadow=-1;ui.role='';ui.index=0;ui.step='listen';remember();render();}
  function chooseModule(value){leave();ui.module=value;ui.round=0;ui.role='';ui.shadow=-1;ui.index=0;ui.step='listen';remember();render();}
  function meter(label,done,total,planned=false){const pct=total?Math.round(done/total*100):0;return `<div class="progress-row"><div class="progress-label"><b>${label}</b><span>${planned?'待添加':`${done} / ${total}`}</span></div><div class="meter-line"><div class="meter" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="${total||1}" aria-valuenow="${done}"><i style="width:${pct}%"></i></div>${total&&done===total?`<span class="done-check">${icon('check')}</span>`:''}</div></div>`;}
  function stats(){const understood=Object.values(store.state.marks).filter(m=>m.listen==='understood').length;return `<div class="stats"><div class="stat"><strong>${understood}</strong><span>自己标记听懂的素材</span></div><div class="stat"><strong>${time(store.state.seconds)}</strong><span>累计开口录音 · 分:秒</span></div><div class="stat"><strong>${store.streak()} <small>天</small></strong><span>连续练习记录 · 不要求打卡</span></div><div class="stat"><strong>${store.state.days.length} <small>天</small></strong><span>留下练习手记的日子</span></div></div>`;}
  function home(){
    let cards=units.map(u=>{const p=store.progress(u);return `<button type="button" class="panel unit-card available" data-action="unit" data-unit="${h(u.id)}"><div><div class="eyebrow">${h(u.label)} · READY WHEN YOU ARE</div><h3 lang="en">${h(u.title)}</h3><span class="unit-zh">${h(u.titleZh)}</span><p>${h(u.introduction)}</p><span class="available-link">打开这一单元 →</span></div><div>${meter('听懂进度',...p.listen)}${meter('角色扮演',...p.role)}${meter('故事复述',...p.retell)}<p>${u.dialogues.length} 段对话 · ${u.stories.length} 篇故事 · 1 张主题句型卡</p></div></button>`;}).join('');
    for(let i=units.length;i<8;i++)cards+=`<article class="panel unit-card placeholder" aria-label="第 ${i+1} 单元，主题待添加"><div class="eyebrow">UNIT ${String(i+1).padStart(2,'0')}</div><h3>留给下一段日常</h3><span class="unit-zh">主题待添加 · 尚未开放</span><p>素材准备好，再慢慢开始。</p>${meter('听懂进度',0,0,true)}${meter('角色扮演',0,0,true)}${meter('故事复述',0,0,true)}</article>`;
    return `<section class="hero"><div><div class="eyebrow">YOUR OWN LITTLE LISTENING JOURNAL</div><h1>听见，属于你的节奏。<span lang="en">Listen, at your own pace.</span></h1><p class="hero-copy">一遍没听懂，就再听一遍。把声音慢慢听清，再借一点句型的帮助，试着说出自己的想法。</p><div class="actions">${button('begin',store.state.history.length?'回到我的练习':'从校园生活开始','','primary')}</div></div><aside class="hero-rule"><p class="quote">不是赶着完成，<br>是慢慢听懂。</p><p>每天可以留给自己 15–20 分钟，也可以更短。<br>不评分，不排名，不需要证明什么。</p></aside></section>${stats()}<section aria-labelledby="shelf-title"><div class="section-head"><div><div class="eyebrow">THE UNIT SHELF</div><h2 id="shelf-title">从熟悉的生活开始</h2></div><p>进度来自你的自我标记<br>不是测评结果</p></div><div class="unit-grid">${cards}</div><p class="plan-note">现在先开放 Teenage Life。其余 7 个位置仅是扩充预留，不会生成虚假的完成记录。</p></section>`;
  }
  function attemptText(module,m=material()){return store.state.attempts[`${unit().id}/${module}/${m.id}`]||0;}
  function savedMark(module){const mark=store.state.marks[key()]?.[module];return mark==='again'?'已放入复习本，想听 / 想说的时候再回来。':mark?'已记下你的自我标记。你仍然可以无限次练习。':'无需赶着标记。按你的感觉来。';}
  function selfMark(module){return `<div class="self-mark"><p>${module==='listen'?'现在，这段声音对你来说清楚一些了吗？':'愿意的话，给今天的练习留一句记录。'}</p><div class="actions">${button('mark',module==='listen'?'我听懂了':module==='role'?'我练过这段对话了':'我尝试复述了',`data-module="${module}" data-value="${module==='listen'?'understood':'done'}"`,'primary')}${button('mark',module==='listen'?'还想再听一遍':'还想再练一遍',`data-module="${module}" data-value="again"`)}</div><p class="status-text">${savedMark(module)}</p></div>`;}
  function player(){return `<section class="player" aria-label="反复听播放器"><div class="player-top">${button('play',`${icon('play')}<span id="play-label">${reader.supported?'开始朗读':'朗读不可用'}</span>`,'id="play-main"','primary listen-button')}${button('restart','从头再听','','quiet')}</div><div class="player-progress"><input id="listen-seek" type="range" min="0" max="${material().lines.length-1}" step="1" value="${Math.min(ui.index,material().lines.length-1)}" aria-label="按句定位朗读位置"><span class="step-count" id="listen-position">${Math.min(ui.index+1,material().lines.length)} / ${material().lines.length} 句</span><span id="reading-done" class="done-check" hidden>${icon('check')}</span></div><div class="player-settings"><label>语速 <select data-change="rate" aria-label="朗读语速">${[.75,1,1.25].map(r=>`<option value="${r}" ${store.state.prefs.rate===r?'selected':''}>${r}×</option>`).join('')}</select></label><label><input type="checkbox" data-change="loop" ${ui.loop?'checked':''}>播完继续循环</label>${button('stop-speech','停止','','small quiet')}</div><p class="player-note" id="voice-status">${reader.supported?'使用本设备英语语音；进度条按句定位，不是秒级音轨。':'当前设备没有语音朗读。可以继续看文本、做笔记、开口和录音。'}</p></section>`;}
  function favoriteButton(id,en,zh,source){const active=store.state.favorites.some(f=>f.id===id);return button('favorite',`${icon('book')}${active?'已收藏':'收藏'}`,`data-id="${h(id)}" data-en="${h(en)}" data-zh="${h(zh)}" data-source="${h(source)}" aria-pressed="${active}"`,'small');}
  function transcript(m=material(),reference=false){
    if(!reference&&store.state.prefs.caption==='hidden')return `<div class="caption-hidden"><p>留一点空间，给耳朵。</p><span class="small-copy">字幕只是帮助你的工具。想看时，随时打开。</span></div>`;
    return `<div class="transcript" aria-label="${reference?'完整参考文本':'可点句重听的字幕'}">${m.lines.map((line,i)=>`<article class="sentence ${i===ui.index?'current':''}" data-line="${i}"><button type="button" class="sentence-text" data-action="sentence" data-index="${i}" aria-label="重听第 ${i+1} 句"><span class="speaker">${h(line.s||'Story')}</span>${!reference&&store.state.prefs.caption==='keywords'?line.keys.map(k=>`<span class="keyword" lang="en">${h(k)}</span>`).join(''):`<span class="english" lang="en">${h(line.en)}</span>${store.state.prefs.translation?`<span class="translation">${h(line.zh)}</span>`:''}`}</button><div class="sentence-tools">${favoriteButton(`${unit().id}/${m.id}/${i}`,line.en,line.zh,m.titleZh)}${button('shadow','跟读',`data-index="${i}"`)}</div></article>`).join('')}</div>`;
  }
  function vocabulary(){return `<details class="vocab"><summary>关键词与生词 · 随时取用，不用背完再继续</summary><div class="vocab-grid">${unit().vocabulary.map((v,i)=>`<article class="vocab-item"><strong lang="en">${h(v.word)}</strong><p>${h(v.meaning)}</p><p class="english" lang="en">${h(v.example)}</p>${button('word-audio','听发音',`data-index="${i}"`,'small quiet')}</article>`).join('')}</div></details>`;}
  function recorderPanel(label){return `<section class="recorder" id="recorder" aria-label="本地录音练习"><div class="rec-title">${icon('mic')} ${label}</div><div class="actions">${button('record','开始录音','id="record-start"')}${button('record-stop','结束并保存','id="record-stop" disabled')}<span class="record-timer" id="record-timer" aria-live="off">0:00</span></div><p class="small-copy" id="record-status">录音不上传；保存在这个浏览器，可回放、下载或删除。不录音也能继续。</p><div id="clip-list" class="clips"></div><details class="recognition"><summary>可选：看看近似转写（不是纠错）</summary><label><input id="recognition-consent" type="checkbox" ${ui.recConsent?'checked':''}>我了解：语音转写可能使用浏览器的在线语音服务；启用时语音可能发送至其服务商。不开启也不影响录音和练习。</label><div class="actions">${button('recognize','开始近似转写','id="recognition-start"','small')}${button('recognize-stop','停止转写','','small quiet')}</div><div id="transcription" class="transcription" role="status" aria-live="polite">${window.SpeechRecognition||window.webkitSpeechRecognition?'只展示可能听到的文字，不评价你的表达。':'此浏览器暂不提供语音转写，请使用录音回听即可。'}</div></details></section>`;}
  function listen(){return `${player()}<div class="option-row"><span class="small-copy">字幕</span><div class="segmented" aria-label="字幕显示方式">${[['full','显示全文'],['keywords','只显示关键词'],['hidden','完全隐藏']].map(([mode,label])=>button('caption',label,`data-mode="${mode}" aria-pressed="${store.state.prefs.caption===mode}"`,store.state.prefs.caption===mode?'active':'')).join('')}</div><label class="small-copy"><input type="checkbox" data-change="translation" ${store.state.prefs.translation?'checked':''}> 中文辅助</label></div>${transcript()}<div class="feature-note">点任意一句可以单独重听；点「跟读」后，先听原句，再录下自己的声音。</div>${ui.shadow>=0?`<div class="prompt"><span class="eyebrow">SHADOWING · 逐句模仿</span><p class="english" lang="en">${h(material().lines[ui.shadow].en)}</p>${button('sentence','再听这一句',`data-index="${ui.shadow}"`,'small')}</div>`:''}${recorderPanel(ui.shadow>=0?'跟读这一句 · 可以反复尝试':'跟读与自由开口 · 任选一句或一小段')}${selfMark('listen')}${vocabulary()}`;}
  function role(){
    const m=material();if(!m.roles.includes(ui.role))ui.role=m.roles[0];const rounds=m.lines.map((line,index)=>({line,index})).filter(r=>r.line.s===ui.role);ui.round=Math.min(ui.round,rounds.length-1);const target=rounds[ui.round],partner=target.index>0?m.lines[target.index-1]:null;
    return `<p class="small-copy">听懂对方，再用你自己的说法回应。参考句只是一个选择。</p><div class="role-choice"><label for="role-choice">我来扮演</label><select id="role-choice" data-change="role">${m.roles.map(r=>`<option ${ui.role===r?'selected':''}>${h(r)}</option>`).join('')}</select>${button('role-reset','同一场景重新练','','small quiet')}</div><div class="round-label">自由练习位置 ${ui.round+1} / ${rounds.length} · 可以前后切换，不必录音才能继续</div><div class="prompt"><div class="eyebrow">${partner?`${h(partner.s)} SAYS`:'YOU CAN BEGIN'}</div>${partner?`<p class="english" lang="en">${h(partner.en)}</p><p class="small-copy">${h(partner.zh)}</p>${button('partner-audio','听对方这句','','small')}`:'<p>这一轮由你开口。可以从打招呼或询问信息开始。</p>'}</div><div class="scaffold"><h3>给你一点开口的支架</h3><ul>${m.supports.map(s=>`<li lang="en">${h(s)}</li>`).join('')}</ul><p class="small-copy">这轮可用的关键词：${target.line.keys.map(h).join(' / ')}。换成你的真实想法也很好。</p><details><summary>你可以试试这样说</summary><p class="english" lang="en">${h(target.line.en)}</p><p class="small-copy">${h(target.line.zh)}</p>${button('role-example','听参考表达','','small')}</details></div>${recorderPanel(`我来扮演 ${h(ui.role)} · 第 ${ui.round+1} 轮`)}<div class="actions">${button('role-prev','上一轮',ui.round===0?'disabled':'')}${button('role-next','下一轮',ui.round===rounds.length-1?'disabled':'','primary')}</div><details class="reference"><summary>完整参考对话与可替换句型 · 随时打开</summary><p class="small-copy">可以把时间、地点、活动和理由换成自己的。没有唯一答案。</p>${m.supports.map(s=>`<p class="english" lang="en">${h(s)}</p>`).join('')}${transcript(m,true)}</details>${selfMark('role')}`;
  }
  function notes(){const m=material(),saved=store.state.notes[key()]||{};return `${player()}<p>可以边听边记。笔记是扶手，只写几个词也很好。</p><label class="small-copy"><input type="checkbox" data-change="hints" ${ui.hints?'checked':''}> 显示关键词提示</label><div class="note-grid">${[['Who','人物'],['What','事情'],['When','时间'],['Where','地点'],['Why','原因'],['How','经过']].map(([field,zh])=>`<label class="form-label"><strong>${field} <span class="small-copy">${zh}</span></strong><span class="hint">${ui.hints?h(m.w5h[field]):'写下你想记住的词就好。'}</span><textarea data-note="${field}" aria-label="${field} ${zh}笔记" placeholder="几个词就够了……">${h(saved[field]||'')}</textarea></label>`).join('')}</div><p class="small-copy" id="note-status">笔记自动保存在本机。无需填满六格。</p><div class="actions">${button('retell-step','再看一下字幕','data-step="listen"')}${button('retell-step','带着笔记试着说','data-step="speak"','primary')}</div>`;}
  function retellOutput(){const m=material(),saved=store.state.notes[key()]||{};return `<div class="scaffold"><h3>一句一句，把故事连起来</h3><p class="english" lang="en">This story is about ...<br>First, ... Then, ... After that, ...<br>In the end, ...</p><p class="small-copy">不需要复现每一个词。先说人物和事情，再说经过与结果。</p></div><details class="reference" open><summary>我的 W5H 笔记</summary>${Object.entries(m.w5h).map(([field])=>`<p><span class="eyebrow">${field}</span> ${h(saved[field]||'还没写也没关系，可以回去补几个词。')}</p>`).join('')}</details><p class="small-copy">连接词库 · 点一下，放进可选草稿</p><div class="connectors">${['This story is about','First,','Then,','After that,','Because','However,','Finally,','In the end,'].map(c=>button('connector',h(c),`data-text="${h(c)}"`)).join('')}</div><label class="form-label">我的复述草稿（选填）<textarea id="retell-draft" data-note="draft" placeholder="可以写几个关键词，也可以直接开口。">${h(saved.draft||'')}</textarea></label>${recorderPanel('试着复述 · 每一遍都可以换一种说法')}<details class="reference"><summary>参考复述 · 你可以试试这样说</summary><p class="english" lang="en">${h(m.retelling)}</p>${button('retelling-audio','听参考复述','','small')}<p class="small-copy">这只是一个版本，不是标准答案。你可以换词、换顺序，表达同样的意思。</p></details><div class="scaffold"><h3>给自己的要点提示</h3><p class="small-copy">可以勾一下已经提到的信息，也可以留着下次再说。不计算分数，不作判断。</p><ul class="checklist">${m.points.map((p,i)=>`<li><label><input type="checkbox" data-check="${i}" ${saved.checks?.[i]?'checked':''}>${h(p)}</label></li>`).join('')}</ul><p class="small-copy">还可以听听：人物和事情清楚吗？有没有用 Then / In the end 把前后连起来？只做自己的参考。</p></div>${selfMark('retell')}`;}
  function retell(){return `<div class="step-nav" aria-label="故事复述步骤">${[['listen','1 · 先听懂'],['notes','2 · 留几个词'],['speak','3 · 试着说']].map(([step,label])=>button('retell-step',label,`data-step="${step}"`,ui.step===step?'active':'')).join('')}</div><p class="small-copy">这些是可自由来回的工具，不是必须完成的关卡。</p>${ui.step==='listen'?`${player()}<div class="option-row"><span class="small-copy">字幕</span><div class="segmented">${[['full','显示全文'],['keywords','只显示关键词'],['hidden','完全隐藏']].map(([mode,label])=>button('caption',label,`data-mode="${mode}" aria-pressed="${store.state.prefs.caption===mode}"`,store.state.prefs.caption===mode?'active':'')).join('')}</div></div>${transcript()}${selfMark('listen')}<div class="actions">${button('retell-step','想记几个词，随时可以','data-step="notes"','quiet')}</div>`:ui.step==='notes'?notes():retellOutput()}`;}
  function patterns(){return `<p class="small-copy">一张主题卡，几种日常用途。听一遍，再换成你的校园生活。</p><div class="pattern-grid">${unit().patterns.map((p,i)=>`<article class="pattern-card"><div class="eyebrow">${h(p.type)}</div><p class="english" lang="en">${h(p.en)}</p><p>${h(p.zh)}</p><p class="example" lang="en">${h(p.example)}</p><p>可以替换：${h(p.replace)}</p><div class="actions">${button('pattern-audio','听例句',`data-index="${i}"`,'small')}${favoriteButton(`${unit().id}/pattern/${p.id}`,p.example,p.zh,'主题句型 · '+p.type)}</div></article>`).join('')}</div>${vocabulary()}`;}
  function practice(){const u=unit(),m=material();return `<header class="workspace-head"><div><div class="eyebrow">${h(u.label)} · ${h(u.title)}</div><h1>${h(u.titleZh)}</h1><p>没有关卡，也不限制重练次数。</p></div><div class="actions">${button('page','回单元书架','data-page="home"','small quiet')}</div></header><div class="module-tabs" role="tablist" aria-label="选择练习工具">${[['listen','反复听','LISTEN AGAIN'],['role','角色扮演','ASK & RESPOND'],['retell','故事复述','LISTEN & RETELL'],['patterns','主题句型','WORDS TO BORROW']].map(([module,label,en])=>button('module',`${label}<small>${en}</small>`,`data-module="${module}" role="tab" aria-selected="${ui.module===module}" aria-controls="module-panel"`,ui.module===module?'active':'')).join('')}</div><div class="work-grid"><aside class="material-list" aria-label="选择练习素材"><h2>这一页，听什么？</h2>${(ui.module==='role'?u.dialogues:ui.module==='retell'?u.stories:allMaterials(u)).map(item=>button('material',`<span lang="en">${h(item.title)}</span><small>${h(item.titleZh)} · ${wordCount(item)} 词${item.levelZh?' · '+h(item.levelZh):''}</small>`,`data-id="${item.id}" aria-pressed="${m.id===item.id}"`,'material-button '+(m.id===item.id?'active':''))).join('')}<p class="material-note">先短后长，由你选择。<br>短故事 → 标准故事。<br>250 词以上的长故事留待后续添加。</p></aside><section id="module-panel" class="panel study-panel" role="tabpanel"><header class="material-title"><div class="eyebrow">${h(modules[ui.module])} · ${ui.module==='patterns'?'ONE THEME CARD':m.levelZh||'CAMPUS CONVERSATION'}</div><h2 lang="en">${ui.module==='patterns'?'A few words to make your own.':h(m.title)}</h2><p class="context">${ui.module==='patterns'?'把句型借过来，再放入你自己的想法。':h(m.context)}</p>${ui.module!=='patterns'?`<span class="small-copy">${h(m.goal||'抓住人物、经过和结果，用自己的话连起来。')} · 本模块练习动作 ${attemptText(ui.module)} 次</span>`:''}</header>${ui.module==='listen'?listen():ui.module==='role'?role():ui.module==='retell'?retell():patterns()}</section></div>`;}
  function library(){return `<div class="eyebrow">YOUR EXPRESSION NOTEBOOK</div><h1>好用的表达，留在手边。</h1><p class="muted">不是背诵清单。用得上的时候，回来借一句。</p><div class="library-tabs">${[['patterns','主题句型'],['favorites',`我的收藏 · ${store.state.favorites.length}`],['review','还想再练']].map(([tab,label])=>button('library-tab',label,`data-tab="${tab}"`,ui.library===tab?'active':'')).join('')}</div>${ui.library==='patterns'?patterns():ui.library==='favorites'?favoriteList():reviewList()}`;}
  function favoriteList(){return store.state.favorites.length?`<div class="pattern-grid">${store.state.favorites.map(f=>`<article class="pattern-card"><div class="eyebrow">${h(f.source)}</div><p class="english" lang="en">${h(f.en)}</p><p>${h(f.zh)}</p><div class="actions">${button('favorite-audio','听这句话',`data-id="${h(f.id)}"`,'small')}${button('remove-favorite','移出收藏',`data-id="${h(f.id)}"`,'small quiet')}</div></article>`).join('')}</div>`:empty('给好句留一个位置。','练习中点「收藏」，就能在这里随时回看。');}
  function empty(title,text){return `<div class="empty"><p class="serif">${title}</p><span>${text}</span></div>`;}
  function reviewList(){let items=[];for(const u of units)for(const m of allMaterials(u))for(const module of ['listen','role','retell'])if(store.state.marks[`${u.id}/${m.id}`]?.[module]==='again')items.push({u,m,module});return items.length?`<section class="panel">${items.map(({u,m,module})=>`<article class="review-item"><div><h3 lang="en">${h(m.title)}</h3><p>${h(u.titleZh)} · ${modules[module]} · 想回来时再来</p></div>${button('review-open','再打开',`data-unit="${u.id}" data-id="${m.id}" data-module="${module}"`,'small')}</article>`).join('')}</section>`:empty('这里没有待办压力。','标记「还想再听 / 再练」的素材会留在这里，想练时再回来。');}
  function historyPage(){const grouped=new Map();store.state.history.forEach(item=>{if(!grouped.has(item.day))grouped.set(item.day,[]);grouped.get(item.day).push(item);});return `<div class="eyebrow">THE PRACTICE JOURNAL</div><h1>每一次开口，都可以被记住。</h1><p class="muted">这里只记过程，不评价表现。播放、录音、重练是不同练习动作。</p>${stats()}${grouped.size?[...grouped].map(([date,items])=>`<section><h2 class="history-date">${h(date)}</h2>${items.map(item=>{const u=units.find(u=>u.id===item.unit),m=u&&allMaterials(u).find(m=>m.id===item.material);return `<div class="history-row"><time>${new Date(item.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time><div>${h(item.action)}<div class="muted">${h(u?.titleZh||item.unit)} · ${h(modules[item.module])} · ${h(m?.titleZh||item.material)}</div></div>${m?button('review-open','回到素材',`data-unit="${u.id}" data-id="${m.id}" data-module="${['role','retell'].includes(item.module)?item.module:'listen'}"`,'small quiet'):''}</div>`;}).join('')}</section>`).join(''):empty('第一页，可以从今天开始。','听一次、说一句，或留下一个自我标记，就会有练习手记。')}<section class="panel" style="margin-top:26px"><h2>我的本地录音</h2><p class="small-copy">可以回听、下载或删除。累计时长保留为历史记录，不因删除文件减少。</p><div id="clip-list" class="clips"></div></section>`;}
  function settings(){return `<div class="eyebrow">A LITTLE ROOM FOR YOURSELF</div><h1>声音、记录，都由你掌握。</h1><div class="settings-grid"><section class="panel"><h2>选一个听得舒服的声音</h2><p>使用设备提供的英语语音，不需要 API key。不同手机与电脑的声音可能不同。</p><label class="form-label">英语语音<select id="voice-choice" data-change="voice"><option value="">系统英语（优先英音）</option></select></label><div class="actions">${button('voice-preview','试听一句','','primary')}${button('stop-speech','停止试听')}</div><p id="voice-availability" class="small-copy"></p><p class="small-copy">若没有声音，可以检查系统的英语语音包、媒体音量，或换一个浏览器。暂时不发音时，阅读、录音和自我标记仍可继续。</p></section><section class="panel"><h2>把文字记录收好</h2><p>导出进度、自我标记、笔记、收藏和累计统计。恢复会替换这些文字数据；本地录音文件不受影响。</p><div class="actions">${button('export','导出 JSON 备份','','primary')}<label class="file-label">选择备份<input id="backup-file" type="file" accept=".json,application/json" class="sr-only"></label></div>${ui.pendingImport?`<div class="import-preview"><strong>已读到备份，尚未替换数据</strong><p>${ui.pendingImport.history.length} 条手记 · ${ui.pendingImport.favorites.length} 条收藏。建议先导出当前备份。</p><div class="actions">${button('confirm-import','确认恢复这份备份','','primary')}${button('cancel-import','先不恢复')}</div></div>`:''}<p class="small-copy">音频不放进 JSON。请在练习手记中逐段下载录音。私密模式、清理站点数据或更换设备会影响本地保存，请定期备份。</p></section><section class="panel"><h2>关于隐私与使用环境</h2><ul><li>本站不上传录音、笔记或练习记录，没有后端、账号或付费接口。</li><li>录音使用本地 MediaRecorder 与 IndexedDB。浏览器不支持时，可直接开口，或借助手机录音机。</li><li>系统朗读可能需要联网，取决于设备的语音包。</li><li>可选语音转写可能使用浏览器在线服务，启用前需单独确认；不参与任何评分。</li><li>推荐 HTTPS 或 localhost。直接双击 index.html 可阅读；录音与保存支持以浏览器为准。</li></ul><p class="small-copy">设计与原创素材使用 MIT 许可。主题可以继续扩充，不需要构建工具。</p></section><section class="panel"><h2>给今天的你</h2><p class="serif" style="font-size:24px;color:var(--deep)">听多少遍，都算数。</p><p>不需要把每个空白填满，不需要把每句英语说得一模一样。清楚一点，再自然一点，就很好。</p><p class="english" lang="en">You can try saying it this way.<br>And you can make it your own.</p></section></div>`;}
  function mountCharacterStage(){
    if(ui.page!=='practice'||!['listen','role'].includes(ui.module)||!material().roles)return;
    const m=material(),profiles=unit().characters||{},heading=$('#module-panel .material-title');if(!heading)return;
    const cards=m.roles.map(name=>{
      const person=profiles[name],you=ui.module==='role'&&ui.role===name;
      return `<figure class="character-card ${you?'is-you':''}" data-character="${h(name)}" aria-label="${h(name)}${you?'，你来扮演':''}"><div class="character-frame">${person?.photo?`<img src="${h(person.photo)}" alt="${h(name)} 的角色示意图" style="--portrait-position:${h(person.position||'50% 28%')}" decoding="async">`:''}<span class="character-fallback" ${person?.photo?'hidden':''} aria-hidden="true">${h(name.slice(0,1))}</span><span class="character-badge" hidden></span></div><figcaption><div><strong lang="en">${h(name)}</strong><span class="character-caption">${h(person?.caption||'对话角色 · 角色图待补充')}</span></div>${you?'<span class="your-role">我来扮演</span>':''}</figcaption></figure>`;
    }).join('');
    const deck=`<section class="speaker-deck" aria-label="对话人物与轮次"><div class="speaker-deck-title"><span class="eyebrow">THE VOICES</span><span>听见谁，就看见谁</span></div><div class="character-grid">${cards}</div><p id="character-status" class="character-status" role="status" aria-live="polite"></p></section>`;
    const playerNode=$('#module-panel .player');
    if(ui.module==='listen'&&playerNode){const consoleNode=document.createElement('div');consoleNode.className='conversation-console';playerNode.before(consoleNode);consoleNode.innerHTML=deck;consoleNode.append(playerNode);}
    else heading.insertAdjacentHTML('afterend',deck);
    document.querySelectorAll('.character-frame img').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.nextElementSibling.hidden=false;}));
  }
  function syncCharacterStage(){
    const stage=$('.speaker-deck');if(!stage)return;
    const m=material();let focus=null,phase='idle',lineIndex=null;
    const matches=playback&&playback.unit===unit().id&&playback.material===m.id;
    const target=ui.module==='role'?m.lines.map((line,index)=>({line,index})).filter(r=>r.line.s===ui.role)[ui.round]:null;
    if(target){lineIndex=target.index>0?target.index-1:target.index;focus=m.lines[lineIndex].s;phase=target.index>0?'prompt':'your-turn';}
    if(matches&&(reader.running||reader.finished)&&reader.lines?.[reader.index]?.s){
      focus=reader.lines[reader.index].s;phase=reader.paused?'paused':reader.finished?'finished':ui.speechPhase==='loading'?'loading':'playing';
      lineIndex=playback.main?reader.index:playback.lineIndex??null;
      if(target&&reader.finished&&playback.kind==='partner'){focus=ui.role;phase='your-turn';lineIndex=target.index;}
    }
    if(recorder.active&&recorder.context?.unit===unit().id&&recorder.context?.material===m.id&&recorder.context?.speaker){focus=recorder.context.speaker;phase='recording';}
    const labels={loading:'准备朗读',playing:'正在说话',paused:'已暂停',finished:'刚刚读完',prompt:'对方的回合','your-turn':'轮到你开口',recording:'你的录音'};
    stage.querySelectorAll('[data-character]').forEach(card=>{
      const selected=card.dataset.character===focus;card.classList.toggle('is-current',selected);card.classList.toggle('is-speaking',selected&&phase==='playing');card.dataset.state=selected?phase:'idle';card.setAttribute('aria-current',selected?'true':'false');
      const badge=card.querySelector('.character-badge');badge.hidden=!selected;badge.textContent=selected?labels[phase]||'':'';
    });
    if(ui.module==='role'&&Number.isInteger(lineIndex))document.querySelectorAll('.sentence[data-line]').forEach(row=>row.classList.toggle('current',Number(row.dataset.line)===lineIndex));
    const status=$('#character-status'),text=focus?`${focus} · ${labels[phase]}`:'点播放开始。人物与台词会一起轮换高亮。';if(status.textContent!==text)status.textContent=text;
  }
  function render(){ui.epoch++;document.querySelectorAll('.main-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===ui.page);b.setAttribute('aria-current',b.dataset.page===ui.page?'page':'false');});$('#main').innerHTML=ui.page==='home'?home():ui.page==='practice'?practice():ui.page==='library'?library():ui.page==='history'?historyPage():settings();mountCharacterStage();if($('#clip-list'))renderClips();if(ui.page==='settings')fillVoices();updateRecordUI();updateSpeechUI();}
  function setPosition(index,fraction){if(!playback?.main)return;ui.index=index;const m=material(),range=$('#listen-seek');if(range){range.value=index;range.style.setProperty('--fill',`${(index+fraction)/m.lines.length*100}%`);}if($('#listen-position'))$('#listen-position').textContent=`${index+1} / ${m.lines.length} 句`;document.querySelectorAll('.sentence[data-line]').forEach(row=>row.classList.toggle('current',Number(row.dataset.line)===index));const current=document.querySelector(`.transcript .sentence[data-line="${index}"]`);if(current){const parent=current.parentElement;const top=current.offsetTop-parent.offsetTop;if(top<parent.scrollTop||top+current.offsetHeight>parent.scrollTop+parent.clientHeight)parent.scrollTo({top:Math.max(0,top-40),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}}
  function updateSpeechUI(){if($('#play-label'))$('#play-label').textContent=playback?.main&&reader.running?(reader.paused?'继续朗读':'暂停朗读'):reader.supported?'开始朗读':'朗读不可用';if($('#reading-done'))$('#reading-done').hidden=!(playback?.main&&reader.finished&&!reader.options.single);syncCharacterStage();}
  reader.onState=state=>{ui.speechPhase=state;updateSpeechUI();};reader.onPosition=(index,fraction)=>{setPosition(index,fraction);syncCharacterStage();};reader.onMessage=tell;reader.onVoices=fillVoices;
  function speak(lines,start=0,single=false,main=false,log=false,extra={}){if(recorder.active||recorder.pending){tell('先结束并保存录音，再听原句。这样不会把示范声音录进去。');return;}stopRecognition();playback={main,unit:unit().id,material:material().id,...extra};const context={...playback};const ok=reader.play(lines,start,{single,loop:main&&ui.loop,rate:store.state.prefs.rate,voice:store.state.prefs.voice,onEnd:()=>{if(log)store.log(context.unit,context.material,'listen','听完一轮，仍可随时重听',false);}});if(ok&&log)store.log(context.unit,context.material,'listen',single?'单句重听':'开始反复听',true);updateSpeechUI();}
  function fillVoices(){const select=$('#voice-choice');if(!select)return;const current=store.state.prefs.voice;select.innerHTML='<option value="">系统英语（优先英音）</option>'+reader.voices.map(v=>`<option value="${h(v.voiceURI)}" ${v.voiceURI===current?'selected':''}>${h(v.name)} · ${h(v.lang)}${v.localService?' · 本地语音':''}</option>`).join('');const status=$('#voice-availability');if(status)status.textContent=!reader.supported?'本浏览器没有语音合成接口。':reader.voices.length?`发现 ${reader.voices.length} 种英语语音。声音清单由设备提供。`:'暂未读到英语语音清单，可尝试系统默认语音或稍后重新打开本页。';}
  function recordContext(){const m=material();return {unit:unit().id,material:m.id,module:ui.module,speaker:ui.module==='role'?ui.role:ui.shadow>=0?m.lines[ui.shadow]?.s:null,label:`${m.titleZh} · ${ui.module==='role'?`${ui.role} 第 ${ui.round+1} 轮`:ui.module==='retell'?'故事复述':ui.shadow>=0?`跟读第 ${ui.shadow+1} 句`:'跟读练习'}`};}
  function updateRecordUI(){const start=$('#record-start'),stop=$('#record-stop');if(start){start.disabled=recorder.active||recorder.pending;start.textContent=recorder.pending?'等待麦克风许可…':recorder.active?'正在录音':'开始录音';start.classList.toggle('recording',recorder.active);}if(stop)stop.disabled=!recorder.active;const text=$('#record-status');if(text)text.textContent=recorder.pending?'请在浏览器提示中选择是否允许麦克风。你也可以切换页面，稍后再试。':recorder.active?'正在本地录音。说到你想停的地方，点「结束并保存」。':'录音不上传；保存在这个浏览器，可回放、下载或删除。不录音也能继续。';syncCharacterStage();}
  recorder.onState=updateRecordUI;recorder.onMessage=tell;recorder.onTick=seconds=>{if($('#record-timer'))$('#record-timer').textContent=time(seconds);};
  recorder.onSaved=(clip,persisted)=>{store.state.seconds+=clip.seconds;store.log(clip.unit,clip.material,clip.module,'留下了一段开口录音');if($('#clip-list'))renderClips();tell(persisted?'这段声音已保存在本机。可以回听，也可以再试一遍。':'本机长期保存暂不可用。请先下载这段录音，刷新后可能无法找回。');};
  async function renderClips(){const epoch=ui.epoch,target=$('#clip-list');if(!target)return;const all=await clips.all();if(epoch!==ui.epoch||target!==$('#clip-list'))return;const list=ui.page==='history'?all:all.filter(c=>c.unit===unit().id&&c.material===material().id&&c.module===ui.module);target.innerHTML=list.length?list.map(c=>{let url=clipUrls.get(c.id);if(!url){url=URL.createObjectURL(c.blob);clipUrls.set(c.id,url);}return `<article class="clip"><div class="clip-title">${h(c.label)} · ${dateText(c.createdAt)} · ${time(c.seconds)}</div><audio controls preload="metadata" src="${url}" aria-label="回放 ${h(c.label)}"></audio><div class="actions">${button('download-clip','下载录音',`data-id="${h(c.id)}"`,'small quiet')}${button('delete-clip','删除本段',`data-id="${h(c.id)}"`,'small quiet')}</div></article>`;}).join(''):'<p class="small-copy">这里会放你自己留下的声音。没有录音也完全没关系。</p>';}
  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  function exportBackup(){download(new Blob([JSON.stringify(store.export(),null,2)],{type:'application/json'}),`hear-journal-${HearStore.day()}.json`);tell('文字备份已准备下载。录音请在练习手记中单独保存。');}
  function startRecognition(){
    if(!ui.recConsent){tell('可选转写可能联网。请先阅读并勾选说明，或者直接使用本地录音。');return;}if(recorder.active||recorder.pending){tell('先保存这段录音，再尝试转写。两种工具可以分开使用。');return;}
    const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){tell('此浏览器没有可用的转写接口，录音回听仍然可以使用。');return;}reader.stop();stopRecognition();recognition=new Recognition();recognition.lang='en-GB';recognition.continuous=true;recognition.interimResults=true;const instance=recognition;let final='';recognizing=true;
    instance.onresult=event=>{let interim='';for(let i=event.resultIndex;i<event.results.length;i++){if(event.results[i].isFinal)final+=event.results[i][0].transcript+' ';else interim+=event.results[i][0].transcript;}if($('#transcription'))$('#transcription').textContent=final+interim||'正在听你的表达……';};
    instance.onerror=()=>{recognizing=false;if($('#transcription'))$('#transcription').textContent='转写暂时没有连上。文字可能听不准，直接用录音回听就好。';};instance.onend=()=>{recognizing=false;};
    try{instance.start();if($('#transcription'))$('#transcription').textContent='转写中，仅作近似文字参考，不作评价。';}catch{recognizing=false;tell('转写暂时不能开始。可以直接录音回听。');}
  }
  document.addEventListener('click',async event=>{
    const nav=event.target.closest('.main-nav [data-page]');if(nav){go(nav.dataset.page);return;}const b=event.target.closest('button[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,m=material(),u=unit();
    if(action==='page')go(b.dataset.page);
    else if(action==='begin')go('practice');
    else if(action==='unit'){ui.unit=b.dataset.unit;ui.module='listen';ui.material=unit().dialogues[0].id;ui.round=0;ui.role='';ui.shadow=-1;ui.index=0;ui.step='listen';remember();go('practice');}
    else if(action==='module')chooseModule(b.dataset.module);
    else if(action==='material')chooseMaterial(b.dataset.id);
    else if(action==='play'){if(playback?.main&&reader.running)reader.togglePause();else speak(m.lines,reader.finished?0:Math.min(ui.index,m.lines.length-1),false,true,true);}
    else if(action==='restart')speak(m.lines,0,false,true,true);
    else if(action==='stop-speech')reader.stop();
    else if(action==='sentence')speak(m.lines,Number(b.dataset.index),true,true,true);
    else if(action==='caption'){store.state.prefs.caption=b.dataset.mode;store.save();render();}
    else if(action==='shadow'){reader.stop();ui.shadow=Number(b.dataset.index);if(ui.module==='retell'){ui.step='speak';tell('可以先读这一句，再把故事用自己的话连起来。');}render();$('#recorder')?.scrollIntoView({block:'center',behavior:'smooth'});}
    else if(action==='mark'){store.mark(u.id,m.id,b.dataset.module,b.dataset.value);render();tell(b.dataset.value==='again'?'已留在复习本。不是没完成，只是还想再熟悉一点。':'记下了。想再听、再说多少遍，都由你决定。');}
    else if(action==='favorite'){const added=store.favorite({id:b.dataset.id,unit:u.id,en:b.dataset.en,zh:b.dataset.zh,source:b.dataset.source});render();tell(added?'已收藏。需要时，回来借用这句话。':'已移出收藏。');}
    else if(action==='remove-favorite'){const found=store.state.favorites.find(f=>f.id===b.dataset.id);if(found)store.favorite(found);render();}
    else if(action==='favorite-audio'){const f=store.state.favorites.find(f=>f.id===b.dataset.id);if(f)speak([{en:f.en}]);}
    else if(action==='pattern-audio')speak([{en:u.patterns[Number(b.dataset.index)].example}]);
    else if(action==='word-audio')speak([{en:u.vocabulary[Number(b.dataset.index)].word}]);
    else if(action==='record'){reader.stop();stopRecognition();recorder.start(recordContext());}
    else if(action==='record-stop')recorder.stop();
    else if(action==='download-clip'){const clip=(await clips.all()).find(c=>c.id===b.dataset.id);if(clip)download(clip.blob,`hear-${clip.material}-${clip.createdAt.replace(/[:.]/g,'-')}.${/mp4/.test(clip.blob.type)?'m4a':'webm'}`);}
    else if(action==='delete-clip'){if(confirm('只删除这一段本机录音？练习记录和累计时长会保留。')){const removed=await clips.remove(b.dataset.id);if(!removed){tell('本机暂时无法移除这段录音，请稍后再试。');return;}const url=clipUrls.get(b.dataset.id);if(url)URL.revokeObjectURL(url);clipUrls.delete(b.dataset.id);renderClips();tell('这一段录音已从本机移除。');}}
    else if(action==='role-prev'||action==='role-next'){leave();ui.round+=action==='role-next'?1:-1;render();}
    else if(action==='role-reset'){leave();ui.round=0;store.log(u.id,m.id,'role','重新练习同一情景');render();}
    else if(action==='partner-audio'){const targets=m.lines.map((line,index)=>({line,index})).filter(r=>r.line.s===ui.role);const i=targets[ui.round].index-1;if(i>=0)speak([m.lines[i]],0,true,false,false,{kind:'partner',lineIndex:i});}
    else if(action==='role-example'){const target=m.lines.map((line,index)=>({line,index})).filter(r=>r.line.s===ui.role)[ui.round];speak([target.line],0,true,false,false,{kind:'example',lineIndex:target.index});}
    else if(action==='retell-step'){leave();ui.step=b.dataset.step;render();}
    else if(action==='connector'){const draft=$('#retell-draft');if(draft){draft.setRangeText((draft.value?' ':'')+b.dataset.text+' ',draft.selectionStart,draft.selectionEnd,'end');saveNote('draft',draft.value);draft.focus();}}
    else if(action==='retelling-audio')speak(m.retelling.match(/[^.!?]+[.!?]+|[^.!?]+$/g).map(en=>({en:en.trim()})));
    else if(action==='library-tab'){reader.stop();ui.library=b.dataset.tab;render();}
    else if(action==='review-open'){ui.unit=b.dataset.unit;ui.module=b.dataset.module;ui.material=b.dataset.id;ui.round=0;ui.role='';ui.shadow=-1;ui.step='listen';ui.index=0;remember();go('practice');}
    else if(action==='export')exportBackup();
    else if(action==='confirm-import'){leave();store.restore(ui.pendingImport);ui.pendingImport=null;ui.unit=store.state.last.unit;ui.module=store.state.last.module;ui.material=store.state.last.material;ui.round=0;ui.role='';ui.shadow=-1;ui.index=0;ui.step='listen';render();tell('文字备份已恢复。录音文件没有改动。');}
    else if(action==='cancel-import'){ui.pendingImport=null;render();}
    else if(action==='voice-preview')speak([{en:'Take your time. You can listen again, and make these words your own.'}]);
    else if(action==='recognize')startRecognition();
    else if(action==='recognize-stop'){stopRecognition();tell('已停止转写。刚才的文字只作参考。');}
  });
  function saveNote(field,value){const k=key();store.state.notes[k]??={};store.state.notes[k][field]=value;store.save();if($('#note-status'))$('#note-status').textContent=store.persistent?'已自动保存在本机。几个词就很好。':'暂时无法长期保存，请在离开前导出文字备份。';}
  document.addEventListener('input',event=>{const target=event.target;if(target.dataset.note){saveNote(target.dataset.note,target.value.slice(0,10000));}if(target.id==='listen-seek'){reader.stop();playback={main:true};ui.index=Number(target.value);setPosition(ui.index,0);}});
  document.addEventListener('change',async event=>{
    const el=event.target,change=el.dataset.change;
    if(change==='rate'){store.state.prefs.rate=Number(el.value);store.save();if(reader.running){const lines=reader.lines,index=reader.index,options={...reader.options,rate:store.state.prefs.rate};reader.play(lines,index,options);}}
    else if(change==='loop'){ui.loop=el.checked;if(reader.options)reader.options.loop=ui.loop;}
    else if(change==='translation'){store.state.prefs.translation=el.checked;store.save();render();}
    else if(change==='role'){leave();ui.role=el.value;ui.round=0;store.log(unit().id,material().id,'role',`选择扮演 ${ui.role}，可以自由重练`);render();}
    else if(change==='hints'){ui.hints=el.checked;render();}
    else if(change==='voice'){store.state.prefs.voice=el.value;store.save();reader.stop();}
    else if(el.dataset.check!==undefined){const k=key();store.state.notes[k]??={};store.state.notes[k].checks??=[];store.state.notes[k].checks[Number(el.dataset.check)]=el.checked;store.state.notes[k].checks=Array.from({length:material().points.length},(_,i)=>!!store.state.notes[k].checks[i]);store.save();}
    else if(el.id==='recognition-consent'){ui.recConsent=el.checked;if(!ui.recConsent)stopRecognition();}
    else if(el.id==='listen-seek')speak(material().lines,Number(el.value),true,true,true);
    else if(el.id==='backup-file'){const file=el.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('请使用 2MB 以内的文字 JSON 备份；音频不是此处的备份格式。');ui.pendingImport=store.parseBackup(JSON.parse(await file.text()));render();tell('已读到备份。请在页面确认后再恢复，当前记录尚未改变。');}catch(error){ui.pendingImport=null;tell(error instanceof SyntaxError?'这份文件不是可读取的 JSON，当前记录没有改变。':error.message);}el.value='';}
  });
  window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(pages.includes(page)&&page!==ui.page)go(page);});
  window.addEventListener('beforeunload',event=>{if(recorder.active){event.preventDefault();event.returnValue='';}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&reader.running&&!reader.paused)reader.togglePause();});
  remember();render();
})();
